1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.util.ArrayList;
5	import java.util.List;
6	
7	import jakarta.validation.Valid;
8	import net.officefloor.plugin.variable.Out;
9	import org.springframework.samples.petclinic.mapper.OwnerMapper;
10	import org.springframework.samples.petclinic.model.Owner;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
13	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
14	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
15	import org.springframework.validation.annotation.Validated;
16	import org.springframework.web.bind.annotation.RequestBody;
17	
18	@Validated
19	public class BuildOwner {
20	
21	    public void service(@Valid @RequestBody OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built,
22	            Out<Boolean> sharesHousehold)
23	            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException {
24	        // Publish the request-only 'sharesHousehold' flag for the household duplicate check.
25	        // Not part of the Owner entity, so it travels as a separate variable.
26	        sharesHousehold.set(Boolean.TRUE.equals(request.getSharesHousehold()));
27	        // Normalize the address up front so the required-field check below rejects an address that
28	        // is blank once normalized, and every later comparison sees the stored normalized form.
29	        request.setAddress(Addresses.normalize(request.getAddress()));
30	        List<String> missing = new ArrayList<>();
31	        if (isBlank(request.getFirstName())) {
32	            missing.add("firstName");
33	        }
34	        if (isBlank(request.getLastName())) {
35	            missing.add("lastName");
36	        }
37	        if (isBlank(request.getAddress())) {
38	            missing.add("address");
39	        }
40	        if (isBlank(request.getCity())) {
41	            missing.add("city");
42	        }
43	        if (isBlank(request.getTelephone())) {
44	            missing.add("telephone");
45	        }
46	        if (!missing.isEmpty()) {
47	            throw new MissingOwnerFieldsException(missing);
48	        }
49	        // Normalize the telephone to E.164 form (keep '+'/country code, else assume '+61').
50	        request.setTelephone(Telephones.toE164(request.getTelephone()));
51	        // Email is optional; when present it must be syntactically valid and is stored lower-cased.
52	        request.setEmail(OwnerEmails.normalize(request.getEmail()));
53	        Owner owner = ownerMapper.toOwner(request);
54	        // The effective registration date is the supplied value, or the server's current date when
55	        // none is supplied. Either way it must fall on a business day: a Saturday or Sunday rolls
56	        // forward to the next Monday. Everything derived from the registration date (membership
57	        // number year, daily create-limit) then sees this adjusted business day.
58	        LocalDate registrationDate = owner.getRegistrationDate();
59	        if (registrationDate == null) {
60	            registrationDate = LocalDate.now();
61	        }
62	        owner.setRegistrationDate(toBusinessDay(registrationDate));
63	        built.set(owner);
64	    }
65	
66	    /** Roll a weekend date forward to the next Monday; business days are returned unchanged. */
67	    private static LocalDate toBusinessDay(LocalDate date) {
68	        return switch (date.getDayOfWeek()) {
69	            case SATURDAY -> date.plusDays(2);
70	            case SUNDAY -> date.plusDays(1);
71	            default -> date;
72	        };
73	    }
74	
75	    private static boolean isBlank(String value) {
76	        return value == null || value.isBlank();
77	    }
78	}
